/// \u{1f52c}\uFE0F Queries every authored Raster SQLite column and independently edits complete semantic leaves.
fn raster_independent_sqlite_oracle(bytes:&[u8],mode:&str,encoding:&str)->Vec<u8>{
 use std::io::Write;
 use std::process::{Command,Stdio};
 let directory=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../\u{1f3c5}\uFE0Fstandards/\u{1f516}\uFE0F1/\u{1fa86}\uFE0Fsubsets/\u2733\uFE0Fany/\u{1f9ec}\uFE0Fschema/\u{1f4f8}\uFE0Fsnapshot/\u{1f9eb}\uFE0Ffixtures/\u{1fab6}\uFE0Fsqlite/\u{1f52c}\uFE0Findependent");
 let script=r#"
import{Database}from'bun:sqlite';import{deepStrictEqual,ok}from'node:assert';import Ajv from'ajv';
const expected=await Bun.file(process.argv[1]).json(),schema=await Bun.file(process.argv[2]).json(),mode=process.argv[3],encoding=process.argv[4];
const validator=new Ajv({strict:true}).compile(schema);ok(validator(expected),JSON.stringify(validator.errors));
const bytes=new Uint8Array(await Bun.stdin.arrayBuffer()),database=Database.deserialize(bytes,{safeIntegers:true});
const names=Object.keys(expected.tables).sort(),key=value=>String(value),same=(left,right)=>key(left)===key(right);
function verify(){
 deepStrictEqual(database.query('PRAGMA integrity_check').all(),[{integrity_check:'ok'}]);deepStrictEqual(database.query('PRAGMA foreign_key_check').all(),[]);
 const tables=names.slice();if(encoding!=='none'){ok(expected.metadata.encodings.includes(encoding));tables.push('semio_snapshot');deepStrictEqual(database.query('PRAGMA table_info(semio_snapshot)').all().map(row=>row.name),expected.metadata.columns);deepStrictEqual(database.query('SELECT '+expected.metadata.columns.join(',')+' FROM semio_snapshot ORDER BY id').all(),[{id:BigInt(expected.metadata.id),artifact_kind:expected.metadata.artifactKind,standard:expected.metadata.standard,subset:expected.metadata.subset,schema_version:BigInt(expected.metadata.schemaVersion),native_encoding:encoding}]);}deepStrictEqual(database.query("SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name").all().map(row=>row.name),tables.sort());
 const rows={},lookup={};
 for(const name of names){const columns=expected.tables[name].columns;deepStrictEqual(database.query('PRAGMA table_info('+name+')').all().map(row=>row.name),columns);rows[name]=database.query('SELECT '+columns.join(',')+' FROM '+name+' ORDER BY id').all();lookup[name]=new Map(rows[name].map(row=>[key(row.id),row]));deepStrictEqual(lookup[name].size,rows[name].length);}
 const identities={document:new Map(),layer:new Map(),scalar64:new Map(),scalar32:new Map(),asset:new Map(),parameter:new Map(),value:new Map(),item:new Map(),member:new Map()};
 const assign=(name,id,path)=>{ok(id!==null);const map=identities[name];ok(!map.has(key(id)),'shared or cyclic '+name);ok(!Array.from(map.values()).includes(path),'duplicate path '+name);map.set(key(id),path);};
 const resolve=(name,id)=>{if(id===null)return null;const value=identities[name].get(key(id));ok(value!==undefined,'unowned '+name+' '+id);return value;};
 const ordered=(values,column,parent)=>{const selected=values.filter(row=>same(row[column],parent)).sort((a,b)=>Number(a.ordinal-b.ordinal));selected.forEach((row,index)=>deepStrictEqual(row.ordinal,BigInt(index)));return selected;};
 deepStrictEqual(rows.raster_document.length,1);const document=rows.raster_document[0];assign('document',document.id,'document');
 for(const row of ordered(rows.raster_asset,'document',document.id))assign('asset',row.id,'asset/'+row.ordinal);
 function layer(row,path,parent){ok((row.document===null)!==(row.parent===null));if(parent===null){ok(same(row.document,document.id));deepStrictEqual(row.parent,null);}else{deepStrictEqual(row.document,null);ok(same(row.parent,parent));}assign('layer',row.id,path);assign('scalar32',row.opacity,path+'/opacity');const children=ordered(rows.raster_layer,'parent',row.id);if(row.kind!=='group')deepStrictEqual(children.length,0);for(const child of children)layer(child,path+'/'+child.ordinal,row.id);}
 for(const row of ordered(rows.raster_layer,'document',document.id))layer(row,'layer/'+row.ordinal,null);
 deepStrictEqual(identities.layer.size,rows.raster_layer.length);
 for(const name of ['raster_transform','raster_mask_transform'])for(const row of rows[name]){const path=resolve('layer',row.id)+(name==='raster_transform'?'/transform/':'/mask/');for(const field of ['x','y','a','b','c','d'])assign('scalar64',row[field],path+field);}
 function value(id,path){assign('value',id,path);const row=lookup.raster_value.get(key(id));ok(row);if(row.kind==='object'){ok(lookup.raster_object.has(key(id)));for(const edge of ordered(rows.raster_member,'object',id)){assign('member',edge.id,'member/'+edge.ordinal);value(edge.value,'value/m'+edge.ordinal);}}else if(row.kind==='array'){ok(lookup.raster_array.has(key(id)));for(const edge of ordered(rows.raster_item,'array',id)){assign('item',edge.id,'item/'+edge.ordinal);value(edge.value,'value/i'+edge.ordinal);}}else if(row.kind==='float'){const scalar=lookup.raster_float.get(key(id));ok(scalar);assign('scalar64',scalar.scalar,path+'/scalar');}else ok(['null','boolean','signed','unsigned','text','bytes'].includes(row.kind));}
 for(const row of rows.raster_parameter){resolve('layer',row.adjustment);assign('parameter',row.id,'parameter/'+row.ordinal);value(row.root,'value/root');}
