 let reprojection=expected_snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();raster_independent_sqlite_oracle(&export_sqlite_database(&reprojection,Default::default(),&mut |_|true).unwrap(),"edited","none");
 semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("raster-independent").label("Raster independent semantic SQLite").version("0.0.1").package_id("semio:raster-independent").artifact(crate::declaration().unwrap()).try_build().unwrap();
